window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6fdf6c3fb5fae171"]={"versions": [{"id": "FIG-6fdf6c3fb5fae171", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM 2.0 / UML-Aktivitätsdiagramm zur AUTOSAR Adaptive Methodology. Das Diagramm spezifiziert den methodischen Teilprozess zur Erstellung eines Software Packages (<code>Create Software Package</code>) im Kontext des Software Deployments für die AUTOSAR Adaptive Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Rolle &amp; Aktivität:</strong></p>\n<ul class=\"fig-list\"><li>Rolle: <code>+Software Deployment Integrator</code> (Tier 1), verknüpft über die Relation <code>«performs»</code> mit der übergeordneten Verbundaktivität <code>Create Software Package</code>.\n</li></ul>\n<p class=\"fig-p\"><strong>Eingangsartefakte (Work Products / Deliverables, Relation <code>«input»</code>):</strong></p>\n<ul class=\"fig-list\"><li><code>Software Cluster Design</code> (Multiplizität <code>1</code>)\n</li><li><code>Uploadable Design Artifacts</code> (Multiplizität <code>0..1</code>)\n</li><li><code>Executable Application</code> (Multiplizität <code>0..*</code>)\n</li><li><code>Application Manifest</code> (Multiplizität <code>0..*</code>)\n</li><li><code>Service Instance Manifest</code> (Multiplizität <code>0..*</code>)\n</li><li><code>Diagnostic Machine Extract</code> (Multiplizität <code>0..1</code>)\n</li></ul>\n<p class=\"fig-p\"><strong>Prüfbeziehung:</strong></p>\n<ul class=\"fig-list\"><li>Abhängigkeit <code>check_consistency</code> (gestrichelter Pfeil) zur Referenzentität <code>Configured Machine on Adaptive ECU</code>.\n</li></ul>\n<p class=\"fig-p\"><strong>Untergeordnete Aktivitäten (Relation <code>«nesting»</code> von <code>Create Software Package</code>):</strong></p>\n<ul class=\"fig-list\"><li><code>Create an initial Software Package Manifest</code>\n</li><li><code>Collect all software artifacts that belong to a Software Cluster</code> (selbst zusammengesetzte Aktivität, schachtelt via <code>«nesting»</code> die Schritte <code>Identify necessary (software) artifacts</code> und <code>Collect belonging (software) artifacts</code>)\n</li><li><code>Model dependencies between Software Clusters of any category</code>\n</li><li><code>Create installation instructions</code>\n</li><li><code>Compile the Software Package</code>\n</li><li><code>Manage the data base of Software Clusters (of any category)</code>\n</li></ul>\n<p class=\"fig-p\"><strong>Ausgangsartefakt (Work Product, Relation <code>«output»</code>):</strong></p>\n<ul class=\"fig-list\"><li><code>Software Package</code> (Multiplizität <code>1</code>)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Software Deployment Integrator initiiert und steuert die Gesamtaktivität <code>Create Software Package</code>. Zu Beginn werden auf Basis des <code>Software Cluster Design</code> sowie optionaler <code>Uploadable Design Artifacts</code> die zugehörigen Software-Artefakte gesammelt (<code>Collect all software artifacts that belong to a Software Cluster</code> mit vorgelagerter Identifikation und Sammlung). Parallel bzw. vorbereitend wird ein initiales Manifest erzeugt (<code>Create an initial Software Package Manifest</code>). Auf Basis der Manifeste (<code>Application Manifest</code>, <code>Service Instance Manifest</code>), der ausführbaren Anwendungen (<code>Executable Application</code>) und des Diagnoseauszugs (<code>Diagnostic Machine Extract</code>) werden Abhängigkeiten zwischen Software Clustern modelliert (<code>Model dependencies between Software Clusters of any category</code>) und Installationsanweisungen definiert (<code>Create installation instructions</code>). Gegen die Zielkonfiguration <code>Configured Machine on Adaptive ECU</code> wird eine Konsistenzprüfung (<code>check_consistency</code>) durchgeführt. Abschließend erfolgt die Paketierung (<code>Compile the Software Package</code>) zum resultierenden <code>Software Package</code>, während die Clusterdatenbank gepflegt wird (<code>Manage the data base of Software Clusters (of any category)</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert verbindliche Eingangs- und Ausgangsartefakte für das Adaptive-Packaging:</p>\n<ul class=\"fig-list\"><li>Das Vorhandensein eines <code>Software Cluster Design</code> ist obligatorisch (<code>1</code>), ebenso die Erzeugung genau eines <code>Software Package</code> (<code>1</code>).\n</li><li>Binäre Ausführungsdateien (<code>Executable Application</code>), Applikationsmanifeste (<code>Application Manifest</code>) und Service-Instanz-Manifeste (<code>Service Instance Manifest</code>) können mehrfach vorliegen (<code>0..*</code>).\n</li><li>Diagnoseauszug (<code>Diagnostic Machine Extract</code>) und hochladbare Entwurfsartefakte (<code>Uploadable Design Artifacts</code>) sind optional (<code>0..1</code>).\n</li><li>Die Konsistenzprüfung gegen <code>Configured Machine on Adaptive ECU</code> ist eine methodische Vorbedingung vor der finalen Freigabe des Pakets.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2a658a951f411ca8", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM 2.0 / UML-Aktivitätsdiagramm zur AUTOSAR Adaptive Methodology. Das Diagramm spezifiziert den methodischen Teilprozess zur Erstellung eines Software Packages (<code>Create Software Package</code>) im Kontext des Software Deployments für die AUTOSAR Adaptive Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Rolle &amp; Aktivität:</strong></p>\n<ul class=\"fig-list\"><li>Rolle: <code>+Software Deployment Integrator</code> (Tier 1), verknüpft über die Relation <code>«performs»</code> mit der übergeordneten Verbundaktivität <code>Create Software Package</code>.\n</li></ul>\n<p class=\"fig-p\"><strong>Eingangsartefakte (Work Products / Deliverables, Relation <code>«input»</code>):</strong></p>\n<ul class=\"fig-list\"><li><code>Software Cluster Design</code> (Multiplizität <code>1</code>)\n</li><li><code>Uploadable Design Artifacts</code> (Multiplizität <code>0..1</code>)\n</li><li><code>Executable Application</code> (Multiplizität <code>0..*</code>)\n</li><li><code>Execution Manifest</code> (Multiplizität <code>0..*</code>)\n</li><li><code>Service Instance Manifest</code> (Multiplizität <code>0..*</code>)\n</li><li><code>Tier 1 Diagnostic Machine Extract</code> (Multiplizität <code>0..1</code>)\n</li></ul>\n<p class=\"fig-p\"><strong>Prüfbeziehung:</strong></p>\n<ul class=\"fig-list\"><li>Abhängigkeit <code>check_consistency</code> (gestrichelter Pfeil) zur Referenzentität <code>Configured Machine on Adaptive ECU</code>.\n</li></ul>\n<p class=\"fig-p\"><strong>Untergeordnete Aktivitäten (Relation <code>«nesting»</code> von <code>Create Software Package</code>):</strong></p>\n<ul class=\"fig-list\"><li><code>Create an initial Software Package Manifest</code>\n</li><li><code>Collect all software artifacts that belong to a Software Cluster</code> (selbst zusammengesetzte Aktivität, schachtelt via <code>«nesting»</code> die Schritte <code>Identify necessary (software) artifacts</code> und <code>Collect belonging (software) artifacts</code>)\n</li><li><code>«SPEM_Task...» Model dependencies between Software Clusters of any category (from Tasks)</code>\n</li><li><code>«SPEM_Task...» Create installation instructions (from Tasks)</code>\n</li><li><code>Compile the Software Package</code>\n</li><li><code>Manage the data base of Software Clusters (of any category)</code>\n</li></ul>\n<p class=\"fig-p\"><strong>Ausgangsartefakt (Work Product, Relation <code>«output»</code>):</strong></p>\n<ul class=\"fig-list\"><li><code>Software Package</code> (Multiplizität <code>1</code>)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Software Deployment Integrator initiiert und steuert die Gesamtaktivität <code>Create Software Package</code>. Zu Beginn werden auf Basis des <code>Software Cluster Design</code> sowie optionaler <code>Uploadable Design Artifacts</code> die zugehörigen Software-Artefakte gesammelt (<code>Collect all software artifacts that belong to a Software Cluster</code> mit vorgelagerter Identifikation und Sammlung). Parallel bzw. vorbereitend wird ein initiales Manifest erzeugt (<code>Create an initial Software Package Manifest</code>). Auf Basis der Manifeste (<code>Execution Manifest</code>, <code>Service Instance Manifest</code>), der ausführbaren Anwendungen (<code>Executable Application</code>) und des Diagnoseauszugs (<code>Tier 1 Diagnostic Machine Extract</code>) werden Abhängigkeiten zwischen Software Clustern modelliert (<code>Model dependencies between Software Clusters of any category</code>) und Installationsanweisungen definiert (<code>Create installation instructions</code>). Gegen die Zielkonfiguration <code>Configured Machine on Adaptive ECU</code> wird eine Konsistenzprüfung (<code>check_consistency</code>) durchgeführt. Abschließend erfolgt die Paketierung (<code>Compile the Software Package</code>) zum resultierenden <code>Software Package</code>, während die Clusterdatenbank gepflegt wird (<code>Manage the data base of Software Clusters (of any category)</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert verbindliche Eingangs- und Ausgangsartefakte für das Adaptive-Packaging:</p>\n<ul class=\"fig-list\"><li>Das Vorhandensein eines <code>Software Cluster Design</code> ist obligatorisch (<code>1</code>), ebenso die Erzeugung genau eines <code>Software Package</code> (<code>1</code>).\n</li><li>Binäre Ausführungsdateien (<code>Executable Application</code>), Ausführungsmanifeste (<code>Execution Manifest</code>) und Service-Instanz-Manifeste (<code>Service Instance Manifest</code>) können mehrfach vorliegen (<code>0..*</code>).\n</li><li>Diagnoseauszug (<code>Tier 1 Diagnostic Machine Extract</code>) und hochladbare Entwurfsartefakte (<code>Uploadable Design Artifacts</code>) sind optional (<code>0..1</code>).\n</li><li>Die Konsistenzprüfung gegen <code>Configured Machine on Adaptive ECU</code> ist eine methodische Vorbedingung vor der finalen Freigabe des Pakets.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8308d5978cf5a375", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM 2.0 / UML-Aktivitätsdiagramm zur AUTOSAR Adaptive Methodology. Das Diagramm spezifiziert den methodischen Teilprozess zur Erstellung eines Software Packages (<code>Create Software Package</code>) im Kontext des Software Deployments für die AUTOSAR Adaptive Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Rolle &amp; Aktivität:</strong></p>\n<ul class=\"fig-list\"><li>Rolle: <code>+Software Deployment Integrator</code> (Tier 1), verknüpft über die Relation <code>«performs»</code> mit der übergeordneten Verbundaktivität <code>Create Software Package</code>.\n</li></ul>\n<p class=\"fig-p\"><strong>Eingangsartefakte (Work Products / Deliverables, Relation <code>«input»</code>):</strong></p>\n<ul class=\"fig-list\"><li><code>Software Cluster Design</code> (Multiplizität <code>1</code>)\n</li><li><code>Uploadable Design Artifacts</code> (Multiplizität <code>0..1</code>)\n</li><li><code>Executable Application</code> (Multiplizität <code>0..*</code>)\n</li><li><code>Execution Manifest</code> (Multiplizität <code>0..*</code>)\n</li><li><code>Service Instance Manifest</code> (Multiplizität <code>0..*</code>)\n</li><li><code>Tier 1 Diagnostic Machine Extract</code> (Multiplizität <code>0..1</code>)\n</li></ul>\n<p class=\"fig-p\"><strong>Prüfbeziehung:</strong></p>\n<ul class=\"fig-list\"><li>Abhängigkeit <code>check_consistency</code> (gestrichelter Pfeil) zur Referenzentität <code>Configured Machine on Adaptive ECU</code>.\n</li></ul>\n<p class=\"fig-p\"><strong>Untergeordnete Aktivitäten (Relation <code>«nesting»</code> von <code>Create Software Package</code>):</strong></p>\n<ul class=\"fig-list\"><li><code>Create an initial Software Package Manifest</code>\n</li><li><code>Collect all software artifacts that belong to a Software Cluster</code> (selbst zusammengesetzte Aktivität, schachtelt via <code>«nesting»</code> die Schritte <code>Identify necessary (software) artifacts</code> und <code>Collect belonging (software) artifacts</code>)\n</li><li><code>«SPEM_Task...» Model dependencies between Software Clusters of any category (from Tasks)</code>\n</li><li><code>«SPEM_Task...» Create installation instructions (from Tasks)</code>\n</li><li><code>Compile the Software Package</code>\n</li><li><code>Manage the data base of Software Clusters (of any category)</code>\n</li></ul>\n<p class=\"fig-p\"><strong>Ausgangsartefakt (Work Product, Relation <code>«output»</code>):</strong></p>\n<ul class=\"fig-list\"><li><code>Software Package</code> (Multiplizität <code>1</code>)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Software Deployment Integrator initiiert und steuert die Gesamtaktivität <code>Create Software Package</code>. Zu Beginn werden auf Basis des <code>Software Cluster Design</code> sowie optionaler <code>Uploadable Design Artifacts</code> die zugehörigen Software-Artefakte gesammelt (<code>Collect all software artifacts that belong to a Software Cluster</code> mit vorgelagerter Identifikation und Sammlung). Parallel bzw. vorbereitend wird ein initiales Manifest erzeugt (<code>Create an initial Software Package Manifest</code>). Auf Basis der Manifeste (<code>Execution Manifest</code>, <code>Service Instance Manifest</code>), der ausführbaren Anwendungen (<code>Executable Application</code>) und des Diagnoseauszugs (<code>Tier 1 Diagnostic Machine Extract</code>) werden Abhängigkeiten zwischen Software Clustern modelliert (<code>Model dependencies between Software Clusters of any category</code>) und Installationsanweisungen definiert (<code>Create installation instructions</code>). Gegen die Zielkonfiguration <code>Configured Machine on Adaptive ECU</code> wird eine Konsistenzprüfung (<code>check_consistency</code>) durchgeführt. Abschließend erfolgt die Paketierung (<code>Compile the Software Package</code>) zum resultierenden <code>Software Package</code>, während die Clusterdatenbank gepflegt wird (<code>Manage the data base of Software Clusters (of any category)</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert verbindliche Eingangs- und Ausgangsartefakte für das Adaptive-Packaging:</p>\n<ul class=\"fig-list\"><li>Das Vorhandensein eines <code>Software Cluster Design</code> ist obligatorisch (<code>1</code>), ebenso die Erzeugung genau eines <code>Software Package</code> (<code>1</code>).\n</li><li>Binäre Ausführungsdateien (<code>Executable Application</code>), Ausführungsmanifeste (<code>Execution Manifest</code>) und Service-Instanz-Manifeste (<code>Service Instance Manifest</code>) können mehrfach vorliegen (<code>0..*</code>).\n</li><li>Diagnoseauszug (<code>Tier 1 Diagnostic Machine Extract</code>) und hochladbare Entwurfsartefakte (<code>Uploadable Design Artifacts</code>) sind optional (<code>0..1</code>).\n</li><li>Die Konsistenzprüfung gegen <code>Configured Machine on Adaptive ECU</code> ist eine methodische Vorbedingung vor der finalen Freigabe des Pakets.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-fa75a8001a31a36b", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM 2.0 / UML-Aktivitätsdiagramm zur AUTOSAR Adaptive Methodology. Das Diagramm spezifiziert den methodischen Teilprozess zur Erstellung eines Software Packages (<code>Create Software Package</code>) im Kontext des Software Deployments für die AUTOSAR Adaptive Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Rolle &amp; Aktivität:</strong></p>\n<ul class=\"fig-list\"><li>Rolle: <code>+Software Deployment Integrator</code> (Tier 1), verknüpft über die Relation <code>«performs»</code> mit der übergeordneten Verbundaktivität <code>Create Software Package</code>.\n</li></ul>\n<p class=\"fig-p\"><strong>Eingangsartefakte (Work Products / Deliverables, Relation <code>«input»</code>):</strong></p>\n<ul class=\"fig-list\"><li><code>Software Cluster Design</code> (Multiplizität <code>1</code>)\n</li><li><code>Uploadable Design Artifacts</code> (Multiplizität <code>0..1</code>)\n</li><li><code>(Adaptive) Executable</code> (Multiplizität <code>0..*</code>)\n</li><li><code>Execution Manifest</code> (Multiplizität <code>0..*</code>)\n</li><li><code>Service Instance Manifest</code> (Multiplizität <code>0..*</code>)\n</li><li><code>Diagnostic Machine Extract</code> (Multiplizität <code>0..1</code>)\n</li></ul>\n<p class=\"fig-p\"><strong>Prüfbeziehung:</strong></p>\n<ul class=\"fig-list\"><li>Abhängigkeit <code>check_consistency</code> (gestrichelter Pfeil) zur Referenzentität <code>Configured Machine on Adaptive ECU</code>.\n</li></ul>\n<p class=\"fig-p\"><strong>Untergeordnete Aktivitäten (Relation <code>«nesting»</code> von <code>Create Software Package</code>):</strong></p>\n<ul class=\"fig-list\"><li><code>Create an initial Software Package Manifest</code>\n</li><li><code>Collect all software artifacts that belong to a Software Cluster</code> (selbst zusammengesetzte Aktivität, schachtelt via <code>«nesting»</code> die Schritte <code>Identify necessary (software) artifacts</code> und <code>Collect belonging (software) artifacts</code>)\n</li><li><code>«SPEM_Task...» Model dependencies between Software Clusters of any category (from Tasks)</code>\n</li><li><code>«SPEM_Task...» Create installation instructions (from Tasks)</code>\n</li><li><code>Compile the Software Package</code>\n</li><li><code>Manage the data base of Software Clusters (of any category)</code>\n</li></ul>\n<p class=\"fig-p\"><strong>Ausgangsartefakt (Work Product, Relation <code>«output»</code>):</strong></p>\n<ul class=\"fig-list\"><li><code>Software Package</code> (Multiplizität <code>1</code>)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Software Deployment Integrator initiiert und steuert die Gesamtaktivität <code>Create Software Package</code>. Zu Beginn werden auf Basis des <code>Software Cluster Design</code> sowie optionaler <code>Uploadable Design Artifacts</code> die zugehörigen Software-Artefakte gesammelt (<code>Collect all software artifacts that belong to a Software Cluster</code> mit vorgelagerter Identifikation und Sammlung). Parallel bzw. vorbereitend wird ein initiales Manifest erzeugt (<code>Create an initial Software Package Manifest</code>). Auf Basis der Manifeste (<code>Execution Manifest</code>, <code>Service Instance Manifest</code>), der ausführbaren Binärdateien (<code>(Adaptive) Executable</code>) und des Diagnoseauszugs (<code>Diagnostic Machine Extract</code>) werden Abhängigkeiten zwischen Software Clustern modelliert (<code>Model dependencies between Software Clusters of any category</code>) und Installationsanweisungen definiert (<code>Create installation instructions</code>). Gegen die Zielkonfiguration <code>Configured Machine on Adaptive ECU</code> wird eine Konsistenzprüfung (<code>check_consistency</code>) durchgeführt. Abschließend erfolgt die Paketierung (<code>Compile the Software Package</code>) zum resultierenden <code>Software Package</code>, während die Clusterdatenbank gepflegt wird (<code>Manage the data base of Software Clusters (of any category)</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert verbindliche Eingangs- und Ausgangsartefakte für das Adaptive-Packaging:</p>\n<ul class=\"fig-list\"><li>Das Vorhandensein eines <code>Software Cluster Design</code> ist obligatorisch (<code>1</code>), ebenso die Erzeugung genau eines <code>Software Package</code> (<code>1</code>).\n</li><li>Ausführbare Adaptive-Anwendungen (<code>(Adaptive) Executable</code>), Ausführungsmanifeste (<code>Execution Manifest</code>) und Service-Instanz-Manifeste (<code>Service Instance Manifest</code>) können mehrfach vorliegen (<code>0..*</code>).\n</li><li>Diagnoseauszug (<code>Diagnostic Machine Extract</code>) und hochladbare Entwurfsartefakte (<code>Uploadable Design Artifacts</code>) sind optional (<code>0..1</code>).\n</li><li>Die Konsistenzprüfung gegen <code>Configured Machine on Adaptive ECU</code> ist eine methodische Vorbedingung vor der finalen Freigabe des Pakets.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0b7fca7af8547a7b", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM 2.0 / UML-Aktivitätsdiagramm zur AUTOSAR Adaptive Methodology. Das Diagramm spezifiziert den methodischen Teilprozess zur Erstellung eines Software Packages (<code>Create Software Package</code>) im Kontext des Software Deployments für die AUTOSAR Adaptive Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Rolle &amp; Aktivität:</strong></p>\n<ul class=\"fig-list\"><li>Rolle: <code>+Software Deployment Integrator</code> (Tier 1), verknüpft über die Relation <code>«performs»</code> mit der übergeordneten Verbundaktivität <code>Create Software Package</code>.\n</li></ul>\n<p class=\"fig-p\"><strong>Eingangsartefakte (Work Products / Deliverables, Relation <code>«input»</code>):</strong></p>\n<ul class=\"fig-list\"><li><code>Software Cluster Design</code> (Multiplizität <code>1</code>)\n</li><li><code>Uploadable Design Artifacts</code> (Multiplizität <code>0..1</code>)\n</li><li><code>(Adaptive) Executable</code> (Multiplizität <code>0..*</code>)\n</li><li><code>Execution Manifest</code> (Multiplizität <code>0..*</code>)\n</li><li><code>Service Instance Manifest</code> (Multiplizität <code>0..*</code>)\n</li><li><code>Diagnostic Machine Extract</code> (Multiplizität <code>0..1</code>)\n</li></ul>\n<p class=\"fig-p\"><strong>Prüfbeziehung:</strong></p>\n<ul class=\"fig-list\"><li>Abhängigkeit <code>check_consistency</code> (gestrichelter Pfeil) zur Referenzentität <code>Configured Machine on Adaptive ECU</code>.\n</li></ul>\n<p class=\"fig-p\"><strong>Untergeordnete Aktivitäten (Relation <code>«nesting»</code> von <code>Create Software Package</code>):</strong></p>\n<ul class=\"fig-list\"><li><code>Create an initial Software Package Manifest</code>\n</li><li><code>Collect all software artifacts that belong to a Software Cluster</code> (selbst zusammengesetzte Aktivität, schachtelt via <code>«nesting»</code> die Schritte <code>Identify necessary (software) artifacts</code> und <code>Collect belonging (software) artifacts</code>)\n</li><li><code>«SPEM_Task...» Model dependencies between Software Clusters of any category (from Tasks)</code>\n</li><li><code>«SPEM_Task...» Create installation instructions (from Tasks)</code>\n</li><li><code>Compile the Software Package</code>\n</li><li><code>Manage the data base of Software Clusters (of any category)</code>\n</li></ul>\n<p class=\"fig-p\"><strong>Ausgangsartefakt (Work Product, Relation <code>«output»</code>):</strong></p>\n<ul class=\"fig-list\"><li><code>Software Package</code> (Multiplizität <code>1</code>)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Software Deployment Integrator initiiert und steuert die Gesamtaktivität <code>Create Software Package</code>. Zu Beginn werden auf Basis des <code>Software Cluster Design</code> sowie optionaler <code>Uploadable Design Artifacts</code> die zugehörigen Software-Artefakte gesammelt (<code>Collect all software artifacts that belong to a Software Cluster</code> mit vorgelagerter Identifikation und Sammlung). Parallel bzw. vorbereitend wird ein initiales Manifest erzeugt (<code>Create an initial Software Package Manifest</code>). Auf Basis der Manifeste (<code>Execution Manifest</code>, <code>Service Instance Manifest</code>), der ausführbaren Binärdateien (<code>(Adaptive) Executable</code>) und des Diagnoseauszugs (<code>Diagnostic Machine Extract</code>) werden Abhängigkeiten zwischen Software Clustern modelliert (<code>Model dependencies between Software Clusters of any category</code>) und Installationsanweisungen definiert (<code>Create installation instructions</code>). Gegen die Zielkonfiguration <code>Configured Machine on Adaptive ECU</code> wird eine Konsistenzprüfung (<code>check_consistency</code>) durchgeführt. Abschließend erfolgt die Paketierung (<code>Compile the Software Package</code>) zum resultierenden <code>Software Package</code>, während die Clusterdatenbank gepflegt wird (<code>Manage the data base of Software Clusters (of any category)</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert verbindliche Eingangs- und Ausgangsartefakte für das Adaptive-Packaging:</p>\n<ul class=\"fig-list\"><li>Das Vorhandensein eines <code>Software Cluster Design</code> ist obligatorisch (<code>1</code>), ebenso die Erzeugung genau eines <code>Software Package</code> (<code>1</code>).\n</li><li>Ausführbare Adaptive-Anwendungen (<code>(Adaptive) Executable</code>), Ausführungsmanifeste (<code>Execution Manifest</code>) und Service-Instanz-Manifeste (<code>Service Instance Manifest</code>) können mehrfach vorliegen (<code>0..*</code>).\n</li><li>Diagnoseauszug (<code>Diagnostic Machine Extract</code>) und hochladbare Entwurfsartefakte (<code>Uploadable Design Artifacts</code>) sind optional (<code>0..1</code>).\n</li><li>Die Konsistenzprüfung gegen <code>Configured Machine on Adaptive ECU</code> ist eine methodische Vorbedingung vor der finalen Freigabe des Pakets.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-6fdf6c3fb5fae171", "to": "FIG-2a658a951f411ca8", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Umbenennung des Eingangs-Artefakts von <code>Application Manifest</code> zu <code>Execution Manifest</code>.\n</li><li>Für die Subaktivitäten <code>Model dependencies between Software Clusters of any category</code> und <code>Create installation instructions</code> wird die SPEM-Stereotypisierung auf <code>«SPEM_Task...»</code> und Herkunft <code>(from Tasks)</code> in abgerundeten Rechtecken umgestellt.\n</li><li>Anpassung der Beschriftungs- und Umbruchsanordnung bei <code>Tier 1 Diagnostic Machine Extract</code> sowie geringfügige typografische Bereinigungen bei Stereotyp- und Multiplizitätsplatzierungen.\n</li></ul>"}, {"from": "FIG-2a658a951f411ca8", "to": "FIG-8308d5978cf5a375", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Redaktionelle Layout- und Zeilenumbruchsanpassungen bei mehreren Artefakt- und Aktivitätsbeschriftungen (u. a. <code>Diagnostic Machine / Extract</code>, <code>Configured Machine on / Adaptive ECU</code>, <code>Uploadable Design / Artifacts</code>, <code>Compile the Software / Package</code>).\n</li><li>Das Label der Ausgabekante zum Artefakt <code>Software Package</code> wechselt von getrennter Darstellung (<code>«output»</code> und <code>1</code>) zu einer kombinierten Beschriftung <code>«output» 1</code>.\n</li></ul>"}, {"from": "FIG-8308d5978cf5a375", "to": "FIG-fa75a8001a31a36b", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Umbenennung des Eingangs-Artefakts von <code>Executable Application</code> zu <code>(Adaptive) Executable</code>, was den Typus des bereitgestellten Binärartefakts auf die Adaptive-Platform-Nomenklatur präzisiert.\n</li></ul>"}, {"from": "FIG-fa75a8001a31a36b", "to": "FIG-0b7fca7af8547a7b", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
